&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Alt Heading (heading with no numbering)&quot;&gt;What &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Alt Heading (heading with no numbering)&quot;&gt;you&#39;ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Alt Heading (heading with no numbering)&quot;&gt;&amp;nbsp;be doing&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:280,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
